head.script:
scwin.onpageload = function() {
	//inputCalendar1.disableAfterDate("20231209");
	gridView1.disableAfterDate(1,"20231209"); 

   gridView1.disableBeforeDate(1,"20231201");
};

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		WebSquare.wUnit.getJq('#G_'+$p.id+'gridView1__col2_input').simulate('key-sequence', {
			sequence: '20231231'
		});
	}
	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col2_input').value == '';
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_img').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_img').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_calendar_cell_3_3').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
